                /** @var Tag|null $tag */
                $tag = Tag::query()
                    ->where('tag_category_id', $category->id)
                    ->where('name->it', $value)
                    ->first();

                if ($tag === null) {
                    $tag = new Tag();
                    $tag->tag_category_id = $category->id;
                }
                $tag->setTranslations('name', ['it' => $value, 'en' => $value]);
                $tag->color = $color;
                $tag->save();
                $stats['tags']++;
                if ($color !== null) {
                    $stats['colors']++;
                }
            }
        }
    });

